import React from "react";
import bacgroundVideo from "./back.mp4";

function Section1() {
  return (
    <div>
      <video
        className=" w-full h-screen object-cover  top-0 z-[-91]"
        src={bacgroundVideo}
        loop
        muted
        autoPlay
      ></video>
      <div className=" flex items-center justify-center bg-black absolute top-0 bg-opacity-20 w-full h-screen z-[-1] ">
        <h1 className=" text-center text-6xl">
          Explore The Wonder Of Solar System
        </h1>
      </div>
    </div>
  );
}

export default Section1;
